// Parse and validate rerank parameters
const inputData = $input.all();

let query = '';
let results = [];
let top_k = 5;

if (inputData.length > 0) {
  const data = inputData[0].json;

  // Extract query
  query = data.query || data.q || data.search || data.text || '';

  // Extract results array (from previous search workflow)
  results = data.results || data.chunks || data.items || [];

  // Extract top_k
  top_k = parseInt(data.top_k || data.limit || data.k || 5);
}

if (!query || query.trim() === '') {
  throw new Error('Missing required parameter: query');
}

if (!results || results.length === 0) {
  throw new Error('Missing required parameter: results (must be array from previous search)');
}

// Format results for rerank API
// The API expects results with at minimum: content, score
const formattedResults = results.map(r => ({
  content: r.content || r.text || '',
  score: r.score || 0,
  metadata: r.metadata || {},
  chunk_id: r.chunk_id || r.id || null,
  document_id: r.document_id || null,
  document_name: r.document_name || null
}));

return [{
  json: {
    query: query.trim(),
    results: formattedResults,
    top_k: top_k
  }
}];

// Format reranked results with enhanced metadata
const inputData = $input.all();

if (inputData.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No response from rerank API',
      results: []
    }
  }];
}

const response = inputData[0].json;

if (response.detail || response.error) {
  return [{
    json: {
      success: false,
      error: response.detail || response.error,
      results: []
    }
  }];
}

// API returns 'reranked_results'
if (!response.reranked_results || response.reranked_results.length === 0) {
  return [{
    json: {
      success: true,
      message: 'No reranked results found',
      results: [],
      total_results: 0
    }
  }];
}

const formattedResults = response.reranked_results.map((result, index) => {
  const metadata = result.metadata || {};
  return {
    rank: index + 1,
    rerank_score: result.rerank_score ? result.rerank_score.toFixed(4) : 'N/A',
    original_score: result.original_score ? result.original_score.toFixed(4) : 'N/A',
    score_improvement: result.rerank_score && result.original_score ? 
      (result.rerank_score - result.original_score).toFixed(4) : 'N/A',
    content: result.content || result.text || '',
    document_id: result.document_id || metadata.document_id || 'Unknown',
    document_name: result.document_name || metadata.document_name || 'Unknown',
    document_type: result.document_type || metadata.document_type || 'Unknown',
    chunk_id: result.chunk_id || 'N/A',
    chunk_index: metadata.chunk_index || null,
    hierarchy_level: metadata.hierarchy_level || 'unknown',
    quality_score: metadata.quality_score || null,
    has_context: metadata.has_context || false,
    contextual_description: metadata.contextual_description || '',
    keywords: metadata.keywords || '[]',
    entities: metadata.entities || '[]',
    technical_terms: metadata.technical_terms || '[]',
    department: metadata.department || null,
    standard_compliance: metadata.standard_compliance || '',
    document_url: metadata.document_url || ''
  };
});

return [{
  json: {
    success: true,
    total_results: formattedResults.length,
    query: response.query || 'N/A',
    model: response.model || 'cross-encoder',
    results: formattedResults,
    rerank_metadata: {
      original_count: response.original_count || formattedResults.length,
      reranked_count: formattedResults.length,
      model_used: response.model || 'cross-encoder/ms-marco-MiniLM-L-6-v2',
      avg_score_improvement: formattedResults.length > 0 ?
        (formattedResults.reduce((sum, r) => {
          const improvement = parseFloat(r.score_improvement);
          return sum + (isNaN(improvement) ? 0 : improvement);
        }, 0) / formattedResults.length).toFixed(4) : '0'
    }
  }
}];
